package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"os/exec"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
	"github.com/hashicorp/terraform-plugin-sdk/v2/plugin"
)

func Provider() *schema.Provider {
	return &schema.Provider{
		Schema: map[string]*schema.Schema{
			"endpoint": {
				Type:        schema.TypeString,
				Required:    true,
				DefaultFunc: schema.EnvDefaultFunc("CUSTOMPROV_ENDPOINT", nil),
			},
			"api_key": {
				Type:        schema.TypeString,
				Required:    true,
				Sensitive:   true,
				DefaultFunc: schema.EnvDefaultFunc("CUSTOMPROV_API_KEY", nil),
			},
		},
		ResourcesMap: map[string]*schema.Resource{
			"customprov_deployment": resourceDeployment(),
		},
		ConfigureContextFunc: providerConfigure,
	}
}

func providerConfigure(ctx context.Context, d *schema.ResourceData) (interface{}, diag.Diagnostics) {
	endpoint := d.Get("endpoint").(string)
	apiKey := d.Get("api_key").(string)
	client := &ApiClient{Endpoint: endpoint, ApiKey: apiKey}
	return client, nil
}

type ApiClient struct {
	Endpoint string
	ApiKey   string
}

func resourceDeployment() *schema.Resource {
	return &schema.Resource{
		CreateContext: resourceDeploymentCreate,
		ReadContext:   resourceDeploymentRead,
		DeleteContext: resourceDeploymentDelete,
		Schema: map[string]*schema.Schema{
			"name": {Type: schema.TypeString, Required: true, ForceNew: true},
			"version": {Type: schema.TypeString, Required: true, ForceNew: true},
			"pre_deploy_hook": {Type: schema.TypeString, Optional: true, ForceNew: true},
			"status": {Type: schema.TypeString, Computed: true},
		},
	}
}

func resourceDeploymentCreate(ctx context.Context, d *schema.ResourceData, m interface{}) diag.Diagnostics {
	client := m.(*ApiClient)
	name := d.Get("name").(string)
	version := d.Get("version").(string)

	// Execute pre-deploy hook if specified - VULNERABILITY: command injection
	if hook, ok := d.GetOk("pre_deploy_hook"); ok {
		hookCmd := hook.(string)
		// Intended for simple validation scripts, but no sanitization
		cmd := exec.CommandContext(ctx, "sh", "-c", hookCmd)
		cmd.Env = append(os.Environ(),
			fmt.Sprintf("DEPLOY_NAME=%s", name),
			fmt.Sprintf("DEPLOY_VERSION=%s", version),
		)
		output, err := cmd.CombinedOutput()
		if err != nil {
			return diag.Errorf("pre_deploy_hook failed: %s\nOutput: %s", err, string(output))
		}
	}

	// Call internal deployment API
	payload := map[string]string{"name": name, "version": version}
	jsonPayload, _ := json.Marshal(payload)
	req, _ := http.NewRequestWithContext(ctx, "POST",
		fmt.Sprintf("%s/v1/deployments", strings.TrimRight(client.Endpoint, "/")),
		strings.NewReader(string(jsonPayload)))
	req.Header.Set("Authorization", "Bearer "+client.ApiKey)
	req.Header.Set("Content-Type", "application/json")

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return diag.FromErr(err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != 201 {
		return diag.Errorf("API returned status %d", resp.StatusCode)
	}

	var result map[string]string
	json.NewDecoder(resp.Body).Decode(&result)
	d.SetId(result["id"])
	d.Set("status", result["status"])
	return nil
}

func resourceDeploymentRead(ctx context.Context, d *schema.ResourceData, m interface{}) diag.Diagnostics {
	client := m.(*ApiClient)
	req, _ := http.NewRequestWithContext(ctx, "GET",
		fmt.Sprintf("%s/v1/deployments/%s", strings.TrimRight(client.Endpoint, "/"), d.Id()), nil)
	req.Header.Set("Authorization", "Bearer "+client.ApiKey)
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return diag.FromErr(err)
	}
	defer resp.Body.Close()
	if resp.StatusCode == 404 {
		d.SetId("")
		return nil
	}
	var result map[string]string
	json.NewDecoder(resp.Body).Decode(&result)
	d.Set("status", result["status"])
	return nil
}

func resourceDeploymentDelete(ctx context.Context, d *schema.ResourceData, m interface{}) diag.Diagnostics {
	client := m.(*ApiClient)
	req, _ := http.NewRequestWithContext(ctx, "DELETE",
		fmt.Sprintf("%s/v1/deployments/%s", strings.TrimRight(client.Endpoint, "/"), d.Id()), nil)
	req.Header.Set("Authorization", "Bearer "+client.ApiKey)
	http.DefaultClient.Do(req)
	return nil
}

func main() {
	plugin.Serve(&plugin.ServeOpts{ProviderFunc: Provider})
}
